create extension if not exists pgcrypto;
create table if not exists accounts(id uuid primary key default gen_random_uuid(),email_normalized text not null unique,password_hash text not null,email_verified_at timestamptz,created_at timestamptz not null default now(),disabled_at timestamptz);
create table if not exists profiles(user_id uuid primary key references accounts(id) on delete cascade,display_name text,settings jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists auth_sessions(id uuid primary key default gen_random_uuid(),user_id uuid not null references accounts(id) on delete cascade,token_hash text not null unique,expires_at timestamptz not null,revoked_at timestamptz,created_at timestamptz not null default now());
create table if not exists email_verification_tokens(id uuid primary key default gen_random_uuid(),user_id uuid not null references accounts(id) on delete cascade,token_hash text not null unique,expires_at timestamptz not null,used_at timestamptz,created_at timestamptz not null default now());
create table if not exists password_reset_tokens(id uuid primary key default gen_random_uuid(),user_id uuid not null references accounts(id) on delete cascade,token_hash text not null unique,expires_at timestamptz not null,used_at timestamptz,created_at timestamptz not null default now());
create table if not exists vaults(id uuid primary key default gen_random_uuid(),owner_id uuid not null references accounts(id) on delete cascade,name_ciphertext text not null,wrapped_vault_key text not null,crypto_version integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists vault_members(vault_id uuid not null references vaults(id) on delete cascade,user_id uuid not null references accounts(id) on delete cascade,role text not null check(role in('owner','admin','editor','viewer')),wrapped_member_key text not null,created_at timestamptz not null default now(),primary key(vault_id,user_id));
create table if not exists vault_items(id uuid primary key default gen_random_uuid(),vault_id uuid not null references vaults(id) on delete cascade,owner_id uuid not null references accounts(id) on delete cascade,ciphertext text not null,nonce text not null,crypto_version integer not null default 1,item_version bigint not null default 1,deleted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists devices(id uuid primary key default gen_random_uuid(),user_id uuid not null references accounts(id) on delete cascade,label text not null,platform text not null,public_key text,wrapped_device_key text,last_seen_at timestamptz,revoked_at timestamptz,created_at timestamptz not null default now());
create table if not exists security_events(id bigint generated always as identity primary key,user_id uuid not null references accounts(id) on delete cascade,event_type text not null,device_id uuid,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists auth_sessions_user_idx on auth_sessions(user_id);create index if not exists auth_sessions_expiry_idx on auth_sessions(expires_at);create index if not exists vaults_owner_idx on vaults(owner_id);create index if not exists vault_items_vault_idx on vault_items(vault_id,updated_at);create index if not exists devices_user_idx on devices(user_id);create index if not exists security_events_user_idx on security_events(user_id,created_at desc);
